package Test;

public class Ifelse {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=5;
		if(a>0)
		System.out.println("The number is positive");
		
		
		if(a%2==0) {
			System.out.println("The number is even");
		}else {
			System.out.println("The number is odd");
			
		}
		
	}
}


